<?php declare(strict_types=1); return static fn(PDO $db)=>$db->exec("CREATE TABLE IF NOT EXISTS debourse_lignes (id INT AUTO_INCREMENT PRIMARY KEY,debourse_id INT NOT NULL,categorie VARCHAR(30) NOT NULL,designation VARCHAR(255) NOT NULL,quantite DECIMAL(12,2) NOT NULL DEFAULT 1,prix_unitaire DECIMAL(15,2) NOT NULL DEFAULT 0,montant DECIMAL(15,2) NOT NULL DEFAULT 0,position INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_budget_line_debourse(debourse_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
